<?php
declare(strict_types=1);require_once __DIR__.'/../app/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$format=(string)($_GET['format']??'json');$run=(new ODLab\LabService())->getRun($id);if(!$run){http_response_code(404);die(e(t('error.run_not_found')));}
if($format==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="odlab_run_'.$id.'_conditions.csv"');$out=fopen('php://output','wb');fputcsv($out,['condition','seed','reference_retention','proposal_retention','committed_retention','final_known_accuracy','final_absent_accuracy','proposed','admitted','rejected','gate_status','rollback','api_calls','input_tokens','output_tokens']);foreach(($run['analysis']['rows']??[]) as $r)fputcsv($out,[$r['condition'],$r['seed'],$r['reference_retention'],$r['proposal_retention'],$r['committed_retention'],$r['final_known_accuracy'],$r['final_absent_accuracy'],$r['proposed_count'],$r['admitted_count'],$r['rejected_count'],$r['gate_status'],$r['rollback']?1:0,$r['usage']['api_calls'],$r['usage']['input_tokens'],$r['usage']['output_tokens']]);fclose($out);exit;
}
$package=['run_id'=>$id,'title'=>$run['title'],'objective'=>$run['objective'],'status'=>$run['status'],'software_version'=>$run['software_version'],'provider_model'=>$run['provider_model'],'config_hash'=>$run['config_hash'],'split_hash'=>$run['split_hash'],'code_manifest_hash'=>$run['code_manifest_hash'],'evidence_root_sha256'=>$run['evidence_root_sha256']??null,'analysis_sha256'=>$run['analysis_sha256']??null,'usage_sha256'=>$run['usage_sha256']??null,'integrity'=>$run['integrity']??null,'config'=>$run['config'],'split_manifest'=>$run['split_manifest'],'usage'=>$run['usage'],'analysis'=>$run['analysis'],'condition_evidence'=>$run['condition_evidence'],'events'=>$run['events']];header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="odlab_run_'.$id.'_research_package.json"');echo json_encode($package,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;
